// The passcode page: self-contained (inline CSS, no external requests).
import { readFileSync } from "node:fs";

// The Storey wordmark outline, as generated by scripts/make-wordmark.py.
const WORDMARK = JSON.parse(readFileSync(new URL("../src/lib/wordmark.json", import.meta.url), "utf8")).small;
const WM_H = 22;
const wordmark = `<svg class="wordmark" width="${((WM_H * WORDMARK.viewBox[2]) / WORDMARK.viewBox[3]).toFixed(1)}" height="${WM_H}" viewBox="${WORDMARK.viewBox.join(" ")}" role="img" aria-label="Storey"><path d="${WORDMARK.d}" fill="currentColor"/></svg>`;

export function escapeHtml(value) {
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

const CSS = `
:root{--bg:#eef0ec;--card:#fff;--ink:#1d2422;--muted:#6a736f;--line:#dde1dc;--accent:#0f6e66;--accent-ink:#fff;--err:#b3261e;--err-bg:#fdecea;--shadow:0 1px 2px rgba(29,36,34,.06),0 8px 28px rgba(29,36,34,.08)}
@media (prefers-color-scheme:dark){:root{--bg:#131917;--card:#1b2220;--ink:#e4e9e6;--muted:#98a39e;--line:#2f3936;--accent:#5dbdb2;--accent-ink:#0b1a18;--err:#ffb4ab;--err-bg:#3a1a1a;--shadow:0 1px 2px rgba(0,0,0,.4),0 8px 28px rgba(0,0,0,.45)}}
*{box-sizing:border-box}
html{color-scheme:light dark}
body{margin:0;min-height:100vh;min-height:100dvh;display:flex;align-items:center;justify-content:center;padding:16px;background:var(--bg);color:var(--ink);font:16px/1.5 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;-webkit-text-size-adjust:100%}
main{width:100%;max-width:380px;background:var(--card);border:1px solid var(--line);border-radius:16px;box-shadow:var(--shadow);padding:28px 24px}
/* The lockup, as in the app's top bar: the teal mark, then the wordmark in ink, x-heights level (the wordmark's box runs from the t to the y's tail, hence the nudge). */
h1{margin:0 0 14px;display:flex;align-items:center;gap:10px;line-height:0}
.mark{display:block;width:36px;height:36px;flex:none;color:var(--accent)}
.wordmark{display:block;margin-top:4px;color:var(--ink)}
p{margin:0 0 20px;color:var(--muted)}
label{display:block;margin:0 0 6px;font-weight:600;font-size:.9rem}
input[type=password]{width:100%;font:inherit;padding:12px 14px;color:var(--ink);background:var(--bg);border:1px solid var(--line);border-radius:10px}
input[type=password]:focus{outline:2px solid var(--accent);outline-offset:1px;border-color:var(--accent)}
button{width:100%;margin-top:16px;font:inherit;font-weight:600;padding:12px 14px;border:0;border-radius:10px;background:var(--accent);color:var(--accent-ink);cursor:pointer;min-height:44px}
button:hover{filter:brightness(1.06)}
button:focus-visible{outline:2px solid var(--ink);outline-offset:2px}
.error{margin:0 0 16px;padding:10px 12px;border-radius:10px;background:var(--err-bg);color:var(--err);font-size:.95rem}
`;

/**
 * @param {{ error?: string, next?: string }} options
 *   error: plain message to show above the field; next: safe relative path to return to.
 */
export function renderLoginPage({ error = "", next = "/" } = {}) {
  const errorHtml = error ? `<p class="error" role="alert">${escapeHtml(error)}</p>` : "";
  return `<!doctype html>
<html lang="en-GB">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<meta name="robots" content="noindex, nofollow">
<meta name="color-scheme" content="light dark">
<title>Storey</title>
<style>${CSS}</style>
</head>
<body>
<main>
<h1><svg class="mark" viewBox="0 0 64 64" fill="currentColor" aria-hidden="true"><path d="M10 27L32 9L54 27Z" stroke="currentColor" stroke-width="3" stroke-linejoin="round"/><rect x="12" y="31" width="40" height="10" rx="2"/><rect x="12" y="45" width="40" height="10" rx="2"/></svg>${wordmark}</h1>
<p>Enter the passcode to continue.</p>
${errorHtml}
<form method="post" action="/login">
<input type="hidden" name="next" value="${escapeHtml(next)}">
<label for="passcode">Passcode</label>
<input id="passcode" name="passcode" type="password" autocomplete="current-password" autofocus required>
<button type="submit">Continue</button>
</form>
</main>
</body>
</html>
`;
}
